import json, time
from research_sdk import Client
c = Client('access.json')
jobs = json.load(open('dev_tests/jobs.json'))
while True:
    done = 0
    row = {}
    for m, jid in jobs.items():
        try:
            s = c.status(jid)
            row[m] = s.get('status')
            if s.get('status') not in ('queued','running'):
                done += 1
            else:
                cost = s.get('cost') or {}
                if isinstance(cost, dict):
                    row[m] = s.get('status') + ' $%.2f' % (cost.get('charged_usd', cost.get('estimated_cost',0) or 0))
        except Exception as e:
            row[m] = 'ERR'
    print(json.dumps(row), flush=True)
    if done >= 4:
        break
    time.sleep(15)
print('ALL DONE')
" 2>&1",
